"""Normalize, reduce and export integer polynomial relations."""
from copy import deepcopy
import json
from pathlib import Path
from sage.all import QQ, ZZ, PolynomialRing, matrix, gcd, lcm


def polynomial_ring(data):
    names = list(data['basis']) if 'basis' in data else [v['name'] for v in data['variables']]
    return PolynomialRing(QQ, names=names)


def polynomial_from_terms(ring, relation):
    return ring({tuple(t['exponents']): QQ(t['coefficient']) for t in relation['terms']})


def reduce_export(data, progress=None):
    """Preserve the integer lattice generated by primitive input polynomials.

    Polynomial degrees are reduced separately, so output remains homogeneous.
    LLL applies a unimodular transformation; removing its zero rows removes
    dependencies without shrinking the integer span. No lattice saturation or
    search for a minimal generating set of the polynomial ideal is performed.
    """
    if 'reduction' in data:
        return deepcopy(data)
    result = deepcopy(data)
    R = polynomial_ring(data)
    groups = {}
    zeros = []
    for i, relation in enumerate(data['relations']):
        p = polynomial_from_terms(R, relation)
        if not p:
            zeros.append(i)
            continue
        degrees = {sum(e) for e in p.dict()}
        if len(degrees) != 1:
            raise ValueError('LLL input relations must be homogeneous polynomials')
        denominator = ZZ(lcm(c.denominator() for c in p.dict().values()))
        content = ZZ(gcd(ZZ(c * denominator) for c in p.dict().values()))
        primitive = p * (denominator / content)
        groups.setdefault(degrees.pop(), []).append(primitive)
    output = []
    for degree, entries in sorted(groups.items()):
        coefficients = [{tuple(e): c for e,c in p.dict().items()} for p in entries]
        columns = sorted({e for row in coefficients for e in row}, reverse=True)
        A = matrix(ZZ, [[row.get(e, 0) for e in columns] for row in coefficients])
        if progress:
            progress(f'Degree {degree}: reducing {A.nrows()} integer vectors in {A.ncols()} monomial coordinates')
        all_reduced, T = A.LLL(delta=0.99, transformation=True)
        if progress:
            progress(f'Degree {degree}: LLL finished; verifying the integer lattice transformation')
        if abs(T.det()) != 1 or T*A != all_reduced:
            raise ArithmeticError('LLL did not preserve the integer relation lattice')
        nonzero = [i for i,row in enumerate(all_reduced.rows()) if any(row)]
        reduced = matrix(ZZ, [all_reduced.row(i) for i in nonzero])
        combinations = matrix(ZZ, [T.row(i) for i in nonzero])
        if len(nonzero) != A.rank():
            raise ArithmeticError('LLL did not remove all linear dependencies')
        # Fix signs, but do not divide row contents after LLL: doing so could
        # enlarge the integer lattice. Sign changes are unimodular.
        for i, row in enumerate(reduced.rows()):
            if next(c for c in row if c) < 0:
                reduced.rescale_row(i, -1)
                combinations.rescale_row(i, -1)
        if combinations * A != reduced:
            raise ArithmeticError('LLL transformation verification failed')
        for row in reduced.rows():
            terms = [{'coefficient': str(c), 'exponents': list(map(int,e))}
                     for e,c in zip(columns,row) if c]
            output.append({'degree': int(degree), 'terms': terms})
    result['relations'] = output
    result['reduction'] = {'input_relation_count':len(data['relations']),
                           'rank':len(output), 'zero_relation_indices':zeros}
    return result


def basis_definitions(data):
    if 'basis' in data:
        return dict(data['basis'])
    return {v['name']: 'zeta('+','.join(map(str,v['indices']))+')'
            for v in data['variables']}


def render_text(data):
    R = polynomial_ring(data)
    lines = ([f"Weight {data['weight']}; basis {data['basis_name']}"]
             if 'weight' in data and 'basis_name' in data else [])
    lines.extend(f'{name} = {expression}' for name,expression in basis_definitions(data).items())
    lines.append('')
    for i, relation in enumerate(data['relations']):
        lines.append(f'Relation {i}: {polynomial_from_terms(R, relation)} = 0')
    return '\n'.join(lines)+'\n'


def write_json(data, path):
    """Stream sparse terms, keeping exponent vectors compact on one line."""
    path = Path(path)
    temporary = Path(str(path)+'.tmp')
    with temporary.open('w',encoding='utf-8') as stream:
        stream.write('{\n  "basis": ')
        stream.write(json.dumps(basis_definitions(data),indent=2).replace('\n','\n  '))
        stream.write(',\n  "relations": [\n')
        for i,relation in enumerate(data['relations']):
            stream.write('    {"terms": [\n')
            for j,term in enumerate(relation['terms']):
                stream.write('      '+json.dumps(term,separators=(',',':')))
                stream.write(',\n' if j+1 < len(relation['terms']) else '\n')
            stream.write('    ]}')
            stream.write(',\n' if i+1 < len(data['relations']) else '\n')
        stream.write('  ]\n}\n')
    temporary.replace(path)


def write_export(data, prefix):
    prefix = Path(prefix)
    prefix.parent.mkdir(parents=True, exist_ok=True)
    write_json(data,Path(str(prefix)+'.json'))
    Path(str(prefix)+'.txt').write_text(render_text(data),encoding='utf-8')
